/**
 * THE FOUR FILES MATCH THE PARTS
 *
 * supabase/sql/run-four/ is what the owner runs: every part in
 * supabase/sql/run-now/, text unchanged, in four pastes. It is generated by
 * scripts/build-run-four.py. A part added or edited without rebuilding would
 * leave the four files short of it, and the owner would run them believing
 * nothing was missing. These checks fail first.
 */
import { readdirSync, readFileSync } from "node:fs"
import { join } from "node:path"

let passed = 0
let failed = 0
const failures: string[] = []
function check(name: string, ok: boolean, detail = "") {
  if (ok) { passed++; console.log(`  ok    ${name}`) }
  else { failed++; failures.push(name); console.log(`  FAIL  ${name}${detail ? `\n        ${detail}` : ""}`) }
}
const RN = "supabase/sql/run-now"
const R4 = "supabase/sql/run-four"
const read = (p: string) => readFileSync(join(process.cwd(), p), "utf8")
const FILES = ["1_of_4_core.sql", "2_of_4_library_checkout_uploads.sql", "3_of_4_latest.sql", "4_of_4_storage_policies_and_check.sql"]
const four = FILES.map((f) => read(`${R4}/${f}`))
const all = four.join("\n")
const statements = (text: string) => text.split("\n").slice(1).filter((l) => l.trim() && l.trim() !== "notify pgrst, 'reload schema';")

console.log("\nEvery part is in the four files, text unchanged")
const parts = readdirSync(join(process.cwd(), RN)).filter((f) => /^(0[1-9]|[1-8]\d)_.*\.sql$/.test(f)).sort()
check("there are parts to carry", parts.length >= 26, `${parts.length}`)
const lines = new Set(all.split("\n"))
for (const p of parts) {
  const missing = statements(read(`${RN}/${p}`)).filter((l) => !lines.has(l))
  check(`${p}: every statement, word for word`, missing.length === 0, missing.map((l) => l.slice(0, 100)).join(" | "))
  check(`${p}: named in the file that carries it`, four.some((f) => f.includes(`-- part ${p}`)))
}

console.log("\nEvery part's note is copied whole too, in every folder the owner might run")
/*
  The checks above skip each part's first line, its note. Part 62's note was
  edited after the files were built, so file 2 carried the old note without
  the characters that close it. Postgres answered "unterminated /* comment" and ran
  nothing from file 2 on. A note left open is the whole file lost, so every
  note is checked word for word, in every folder, and every line a file
  opens as a comment closes on that line.
*/
const allInThree = readdirSync(join(process.cwd(), "supabase/sql/all-in-three")).filter((f) => f.endsWith(".sql")).sort().map((f) => read(`supabase/sql/all-in-three/${f}`))
const threeLines = new Set(allInThree.join("\n").split("\n"))
for (const p of parts) {
  const note = read(`${RN}/${p}`).split("\n")[0]
  check(`${p}: its note, word for word, in run-four and all-in-three`, lines.has(note) && threeLines.has(note), note.slice(-80))
}
const unclosed = [...four, ...allInThree].flatMap((f) => f.split("\n")).filter((l) => l.startsWith("/*") && !l.trimEnd().endsWith("*/"))
check("no line opens a comment it does not close", unclosed.length === 0, unclosed.map((l) => l.slice(0, 100)).join(" | "))
for (const dir of ["supabase/sql/all-last-three-days", "supabase/sql/all-last-14-days"])
  check(`${dir} holds the same four files as run-four`, FILES.every((f, i) => read(`${dir}/${f}`) === four[i]))

console.log("\nThe order, and what each file ends with")
const order = parts.map((p) => all.indexOf(`-- part ${p}`))
check("the parts run in their numbered order", order.every((at, i) => at >= 0 && (i === 0 || at > order[i - 1])))
check("files 1 to 3 end with one row that says which file ran", four.slice(0, 3).every((f, i) => f.trimEnd().endsWith(`select 'Storelib file ${i + 1} of 4 ran. Next file.' as done;`)))
const checkAfter = statements(read(`${RN}/99_check_after.sql`)).filter((l) => !l.startsWith("/*"))
check("file 4 ends with the check after, one column per part", checkAfter.length === 1 && four[3].trimEnd().endsWith(checkAfter[0]))
check("the check has a column for every part", parts.every((p) => new RegExp(`as p${p.slice(0, 2)}_`).test(checkAfter[0])))
check("every file lifts the statement timeout for its own transaction only", four.every((f) => /^set local statement_timeout = 0;$/m.test(f)))

console.log("\nWhat can stop on the owner's data skips itself instead")
const p90 = read(`${RN}/90_storage_policies_needs_owner.sql`)
check("file 4 carries the storage policies", four[3].includes(p90.split("\n")[1].split(" begin managed := ")[1].slice(0, 200)))
check("and skips them with a notice when this role cannot own storage.objects",
  /pg_has_role\(current_user, \(select c\.relowner from pg_class c where c\.oid = 'storage\.objects'::regclass\), 'MEMBER'\) then raise notice 'storage policies skipped/.test(four[3]))
check("a refund recorded twice skips the refund-once index with a warning, not an error",
  /IF EXISTS \(SELECT 1 FROM public\.ledger_events WHERE event_type = 'refund' AND stripe_refund_id IS NOT NULL GROUP BY stripe_refund_id, order_id HAVING count\(\*\) > 1\) THEN RAISE WARNING 'part 03 skipped/.test(four[0]))
check("no file deletes a row outside a function body", !/^(delete|truncate)\b/im.test(all))
check("the purge-by-date script is not in them", !/doomed|delete from auth\.users/i.test(all))

console.log("\nNothing slow runs while the orders table is held")
/*
  A file is one transaction and keeps every lock it takes until it ends. The
  file with parts 20 to 89 alters orders early (parts 32, 36, 59), so a slow
  statement after that holds every checkout, webhook and receipt read for as
  long as it takes. Part 61's placing of old page views rewrites every old
  view: 76 s at a million rows, measured with an order read waiting 75 s.
  It runs first in the last file instead, which holds no order table, and
  the same goes for the three files in all-in-three/.
*/
const backfill = read(`${RN}/61_analytics_one_pipeline.sql`).split("\n").filter((l) => l.includes("old page views placed on a property"))
const three = ["1_of_3_core_library_checkout.sql", "2_of_3_latest.sql", "3_of_3_storage_policies_and_check.sql"].map((f) => read(`supabase/sql/all-in-three/${f}`))
check("part 61 places old page views in one statement", backfill.length === 1 && /^DO \$\$/.test(backfill[0]))
check("  which is in no file that alters orders", [...four, ...three].filter((f) => f.includes(backfill[0])).every((f) => !/ALTER TABLE public\.orders\b/.test(f)), "")
check("  and runs first in the last file, before the storage policies and the check", [four[3], three[2]].every((f) => {
  /* The record of which parts ran (part 67) is made first in every file: a table of its own, no lock on anything else. */
  const body = f.split("\n").filter((l) => l.trim() && !l.startsWith("--") && !/^set local /.test(l) && !l.includes("public.storelib_applied_parts"))
  return body[0] === backfill[0]
}))
check("  once in each set of files", four.filter((f) => f.includes(backfill[0])).length === 1 && three.filter((f) => f.includes(backfill[0])).length === 1)

console.log("\nThe oldest email_events shape does not stop the files")
/*
  Part 46 upgrades email_events from its oldest shape (recipient_email,
  required, and no creator_id; supabase/migrations/20260202), but parts 20
  and 21 run before it in the same file and named creator_id outright, so on
  that shape the whole paste stopped at part 20 with "column creator_id does
  not exist" and part 46 never ran. scripts/sql-harness/run.sh (legacy
  scenario) builds that shape and runs both files twice.
*/
const p20 = read(`${RN}/20_saved_cards_bounces_and_exec_sql.sql`)
const p21 = read(`${RN}/21_email_sending.sql`)
check("part 20 relaxes creator_id only where the column is there and required", p20.includes("if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'email_events' and column_name = 'creator_id' and is_nullable = 'NO') then alter table public.email_events alter column creator_id drop not null; end if;"))
check("  and its migration says the same", read("supabase/migrations/20260930_saved_cards_bounces_and_exec_sql.sql").includes(p20.split("\n")[2]))
const addCol = p21.indexOf("ALTER TABLE public.email_events ADD COLUMN IF NOT EXISTS creator_id uuid")
check("part 21 gives email_events a creator_id before its policy reads one", addCol > 0 && addCol < p21.indexOf('CREATE POLICY "Creators read their own email events"'))
const harness = read("scripts/sql-harness/run.sh")
check("the harness runs each file as one query, as the SQL editor does, and with psql -1", harness.includes("simple_query.py") && harness.includes("-1 -v ON_ERROR_STOP=1"))
check("  twice, comparing schema and every row after the second run", /fingerprint "\$db" "\$fp-after-second"/.test(harness))
check("  on the oldest shape too", /recipient_email text not null/.test(read("scripts/sql-harness/legacy.sql")) && !/creator_id/.test(read("scripts/sql-harness/legacy.sql").split("create table public.email_events")[1].split(");")[0]))
const baseFiles = read("scripts/sql-harness/base-files.txt").split("\n").filter((l) => l.trim() && !l.startsWith("#"))
check("every file the harness builds its base from is in the repository", baseFiles.length > 100 && baseFiles.every((f) => { try { read(f); return true } catch { return false } }), baseFiles.filter((f) => { try { read(f); return false } catch { return true } }).join(", "))

console.log(`\n${passed} passed, ${failed} failed`)
if (failed > 0) { console.log(`\nFailed:\n${failures.map((f) => `  - ${f}`).join("\n")}`); process.exit(1) }
